import { NextRequest, NextResponse } from 'next/server'
import { createSupabaseAnon, createSupabaseServer } from '@/lib/supabase/server'
import { PRIVATE_NO_STORE, revalidateProductCatalog } from '@/lib/product-cache'
import { dbToDisplay, displayToDb } from '@/lib/price'

type CategoryLookupRow = {
  slug: string
  parent_slug: string | null
}

async function resolveRootCategorySlug(supabase: any, categorySlug: string) {
  let currentSlug: string | null = categorySlug
  while (currentSlug) {
    const categoryQueryResult: { data: CategoryLookupRow | null } = await supabase
      .from('categories')
      .select('slug,parent_slug')
      .eq('slug', currentSlug)
      .single()
    const categoryData = categoryQueryResult.data

    if (!categoryData) {
      return null
    }

    if (!categoryData.parent_slug) {
      return categoryData.slug
    }

    currentSlug = categoryData.parent_slug
  }

  return null
}

// Helper function to check admin access
async function checkAdminAccess(supabase: any) {
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) {
    return { authorized: false, status: 401, error: 'Unauthorized' }
  }
  
  const { data: profile } = await supabase
    .from('profiles')
    .select('role')
    .eq('id', user.id)
    .single()
  
  if (!profile || profile.role !== 'admin') {
    return { authorized: false, status: 403, error: 'Forbidden: Admin access required' }
  }
  
  return { authorized: true }
}

// GET /api/products/[id] - Get single product
export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const supabase = createSupabaseAnon()
    
    const { data, error } = await supabase
      .from('products')
      .select('*')
      .eq('id', params.id)
      .is('deleted_at', null)
      .single()
    
    if (error || !data) {
      return NextResponse.json(
        { success: false, error: 'Product not found' },
        { status: 404 }
      )
    }
    
    const product = {
      ...data,
      price: dbToDisplay(data.price),
      original_price: data.original_price ? dbToDisplay(data.original_price) : null,
    }
    
    return NextResponse.json(
      { success: true, data: product },
      { headers: { 'Cache-Control': PRIVATE_NO_STORE } }
    )
  } catch (error) {
    console.error('API error:', error)
    return NextResponse.json(
      { success: false, error: 'Failed to fetch product' },
      { status: 500 }
    )
  }
}

// PUT /api/products/[id] - Update product (Admin only)
export async function PUT(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const supabase = await createSupabaseServer()
    
    // Check admin access
    const authCheck = await checkAdminAccess(supabase)
    if (!authCheck.authorized) {
      return NextResponse.json(
        { success: false, error: authCheck.error },
        { status: authCheck.status }
      )
    }
    
    const body = await request.json()
    
    // Convert camelCase to snake_case and price from TL to kuruş
    const updateData: any = {}
    
    // Map field names (camelCase → snake_case)
    if (body.name !== undefined) updateData.name = body.name
    if (body.slug !== undefined) updateData.slug = body.slug
    if (body.brand !== undefined) updateData.brand = body.brand
    // Category handling: category_slug should be the main category, subcategory_slug should be the subcategory
    if (body.category !== undefined || body.subcategory !== undefined) {
      // If subcategory is provided, map category to top-level ancestor
      if (body.subcategory) {
        updateData.subcategory_slug = body.subcategory
        const rootCategorySlug = await resolveRootCategorySlug(supabase, body.subcategory)
        if (rootCategorySlug) {
          updateData.category_slug = rootCategorySlug
        } else {
          // Fallback: use category if provided
          updateData.category_slug = body.category || null
        }
      } else {
        // No subcategory, just set main category
        updateData.category_slug = body.category || null
        updateData.subcategory_slug = null
      }
    }
    if (body.description !== undefined) updateData.description = body.description
    if (body.barcode !== undefined) updateData.barcode = body.barcode
    if (body.image !== undefined) updateData.image = body.image
    if (body.images !== undefined) updateData.images = body.images
    if (body.rating !== undefined) updateData.rating = body.rating
    if (body.reviews !== undefined) updateData.reviews_count = body.reviews
    if (body.discount !== undefined) updateData.discount = body.discount
    
    // Boolean flags (camelCase → snake_case)
    if (body.isNew !== undefined) updateData.is_new = body.isNew
    if (body.isBestSeller !== undefined) updateData.is_best_seller = body.isBestSeller
    if (body.inStock !== undefined) updateData.in_stock = body.inStock
    
    // Stock quantity
    if (body.stock_quantity !== undefined) updateData.stock_quantity = body.stock_quantity
    
    if (body.price !== undefined) {
      updateData.price = displayToDb(body.price)
    }
    if (body.original_price !== undefined) {
      updateData.original_price = body.original_price ? displayToDb(body.original_price) : null
    }
    if (body.originalPrice !== undefined) {
      updateData.original_price = body.originalPrice ? displayToDb(body.originalPrice) : null
    }
    
    const { data, error } = await supabase
      .from('products')
      .update(updateData)
      .eq('id', params.id)
      .select()
      .single()
    
    if (error || !data) {
      return NextResponse.json(
        { success: false, error: error?.message || 'Failed to update product' },
        { status: 500 }
      )
    }
    
    const product = {
      ...data,
      price: dbToDisplay(data.price),
      original_price: data.original_price ? dbToDisplay(data.original_price) : null,
    }

    revalidateProductCatalog()
    
    return NextResponse.json({ success: true, data: product })
  } catch (error) {
    console.error('API error:', error)
    return NextResponse.json(
      { success: false, error: 'Failed to update product' },
      { status: 500 }
    )
  }
}

// DELETE /api/products/[id] - Soft delete product (Admin only)
export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const supabase = await createSupabaseServer()
    
    // Check admin access
    const authCheck = await checkAdminAccess(supabase)
    if (!authCheck.authorized) {
      return NextResponse.json(
        { success: false, error: authCheck.error },
        { status: authCheck.status }
      )
    }
    
    // Soft delete by setting deleted_at
    const { error } = await supabase
      .from('products')
      .update({ deleted_at: new Date().toISOString() })
      .eq('id', params.id)
    
    if (error) {
      return NextResponse.json(
        { success: false, error: error.message },
        { status: 500 }
      )
    }
    
    revalidateProductCatalog()

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('API error:', error)
    return NextResponse.json(
      { success: false, error: 'Failed to delete product' },
      { status: 500 }
    )
  }
}
